// Local proof only: preserve every assertion, vary explicit native runtime budgets.
// No repository Ediel source or test file is modified.
import fs from 'node:fs'
import ts from '/workspace/gridex-ops-platform/node_modules/typescript/lib/typescript.js'
import base from '/workspace/gridex-ops-platform/vitest.config.ts'

const budget = 120000
const targets = new Set([
  '/workspace/gridex-ops-platform/__tests__/ediel-confirmed-customer-final-response.test.ts',
  '/workspace/gridex-ops-platform/__tests__/ediel-sc-010-beneficiary-export.test.ts',
  '/workspace/gridex-ops-platform/__tests__/ediel-prodat-free-text.test.ts',
])

export default {
  ...base,
  plugins: [...(base.plugins ?? []), {
    name: 'local-native-runtime-budget-proof',
    enforce: 'pre',
    transform(code, id) {
      const file = id.split('?')[0]
      if (!targets.has(file)) return null
      const source = ts.createSourceFile(file, code, ts.ScriptTarget.Latest, true)
      const edits = []
      const visit = (node) => {
        if (ts.isCallExpression(node) && /^(?:it|test)(?:$|[.(])/.test(node.expression.getText(source))) {
          const argument = node.arguments[2]
          if (argument && ts.isNumericLiteral(argument) && Number(argument.text) < budget) {
            edits.push({ start: argument.getStart(source), end: argument.end, kind: 'test-registration', before: argument.getText(source) })
          }
        }
        if (ts.isPropertyAssignment(node) && node.name.getText(source) === 'timeout' && ts.isNumericLiteral(node.initializer)) {
          const call = node.parent.parent
          if (ts.isCallExpression(call) && call.expression.getText(source) === 'spawnSync' && Number(node.initializer.text) < budget) {
            edits.push({ start: node.initializer.getStart(source), end: node.initializer.end, kind: 'local-child-runtime', before: node.initializer.getText(source) })
          }
        }
        ts.forEachChild(node, visit)
      }
      visit(source)
      if (!edits.length) throw new Error('native_budget_proof_target_not_transformed:' + file)
      fs.appendFileSync('/tmp/gridex-native-budget-proof-transforms.jsonl', JSON.stringify({ file, budget, edits }) + '\n')
      let transformed = code
      for (const edit of edits.sort((a, b) => b.start - a.start)) {
        transformed = transformed.slice(0, edit.start) + String(budget) + transformed.slice(edit.end)
      }
      return { code: transformed, map: null }
    },
  }],
}
